// app/build.gradle.kts — the number comes from the pipeline, never from a person
val ciRun = (System.getenv("GITHUB_RUN_NUMBER") ?: "0").toInt()
val liveCode = (System.getenv("LIVE_VERSION_CODE") ?: "0").toInt()

android {
    defaultConfig {
        // One monotonic counter feeds internal, closed and production alike.
        // A QA build that never ships still spends its code. That is fine: codes are cheap.
        versionCode = 10_000 + ciRun     // hard ceiling is 2_100_000_000
        versionName = "8.4.0"            // display only, may repeat, not a key
    }
}

// Fail in the first ten seconds instead of after the archive and the upload
tasks.register("assertVersionCode") {
    val candidate = android.defaultConfig.versionCode!!
    doLast {
        require(candidate > liveCode) {
            "versionCode $candidate is not above the $liveCode already on Play — " +
                "the edit will be rejected 20 minutes from now"
        }
    }
}
tasks.named("preBuild") { dependsOn("assertVersionCode") }

// iOS is the same rule under different names:
//   CFBundleShortVersionString = 8.4.0   marketing version, what the store shows
//   CFBundleVersion            = 14213   build number, must beat the last upload
//                                        made for that marketing version
//   agvtool new-version -all "$((10000 + CI_RUN))"
// A repeat comes back as "The provided entity includes an attribute with a value
// that has already been used" — and deleting the old TestFlight build does not free it.

// Android: Play can install it for you — but only if this user can see the release.
private val manager = AppUpdateManagerFactory.create(context)

fun enforce(policy: VersionPolicy) {
    manager.appUpdateInfo.addOnSuccessListener { info ->
        val mustBlock = BuildConfig.VERSION_CODE < policy.minSupportedCode
        val type = when {
            mustBlock || info.updatePriority() >= 4 -> AppUpdateType.IMMEDIATE
            (info.clientVersionStalenessDays() ?: 0) >= 14 -> AppUpdateType.FLEXIBLE
            else -> return@addOnSuccessListener
        }
        if (info.updateAvailability() == UpdateAvailability.UPDATE_AVAILABLE &&
            info.isUpdateTypeAllowed(type)
        ) {
            manager.startUpdateFlowForResult(info, type, activity, REQ_UPDATE)
        } else if (mustBlock) {
            // Nothing on offer: sideloaded, the rollout has not reached them, or their
            // OS is below the new build's minSdk. A hard block here traps them forever.
            showDismissibleNagWithStoreLink()
        }
    }
}

// An immediate update interrupted by a task switch has to be resumed, or the user
// comes back to a half-updated app that will not start.
override fun onResume() {
    super.onResume()
    manager.appUpdateInfo.addOnSuccessListener { info ->
        if (info.updateAvailability() ==
            UpdateAvailability.DEVELOPER_TRIGGERED_UPDATE_IN_PROGRESS
        ) {
            manager.startUpdateFlowForResult(info, AppUpdateType.IMMEDIATE, activity, REQ_UPDATE)
        }
    }
}

