// app/build.gradle.kts
android {
    namespace = "com.example.app"
    compileSdk = 36              // compile against the newest SDK: this part is free

    defaultConfig {
        minSdk = 26              // YOUR call — make it from active installs, not opinions
        targetSdk = 36           // Play's deadline — opts you into Android 16 behaviour
        versionCode = 4213
    }
}

// targetSdk is a behaviour change, not a number change. Going to 36 turns on:
//   - enforced edge-to-edge; windowOptOutEdgeToEdgeEnforcement is ignored
//   - orientation / resizability restrictions ignored on displays >= 600dp
//   - 16 KB page alignment required for every bundled .so
androidComponents {
    onVariants { variant ->
        // Uncompressed, page-aligned native libs — fail here, not in a pre-launch report
        variant.packaging.jniLibs.useLegacyPackaging.set(false)
    }
}

// Verify the thing you are about to upload, not the thing you built last month:
//   zipalign -c -P 16 -v 4 app-release.apk
//   objdump -p lib/arm64-v8a/libfoo.so | grep LOAD     # align must be 2**14

// The iOS half of the same decision lives in an .xcconfig, and only the first
// line is yours:
//   IPHONEOS_DEPLOYMENT_TARGET = 16.0   // your floor; Apple never sets it
//   Apple constrains the SDK you build WITH, not the OS you run ON.

// Whatever you pick, users below the floor are frozen, not gone. Keep the API
// contract they depend on alive, and make sure the force-update gate never
// demands a version their device cannot install.

import StoreKit

// The store decides eligibility. Your paywall copy does not.
func offerLine(for product: Product) async -> String {
    guard let sub = product.subscription else { return product.displayPrice }

    // WRONG: the offer hangs off the product, so this shows "free trial" to everyone,
    // including the user who already burned it on another product in the same group.
    //   if sub.introductoryOffer != nil { return "7 days free" }

    // RIGHT: eligibility is per Apple Account, per subscription GROUP.
    if await sub.isEligibleForIntroOffer, let intro = sub.introductoryOffer {
        return "Free for \(intro.period.value) \(intro.period.unit), then \(product.displayPrice)"
    }
    return "\(product.displayPrice) every \(sub.subscriptionPeriod.value) \(sub.subscriptionPeriod.unit)"
}

// Grace period: do not revoke on the first failed renewal.
func isEntitled(_ status: Product.SubscriptionInfo.Status) -> Bool {
    switch status.state {
    case .subscribed, .inGracePeriod:
        return true                  // still a customer; the card failed, the person did not
    case .inBillingRetryPeriod:
        return false                 // no grace configured — this is the churn you chose
    default:
        return false
    }
}

// Review checks that this exists and works. It is not optional on iOS.
func restorePurchases() async throws { try await AppStore.sync() }

