// The lever you own: a gate whose value comes from the server, read per call,
// with a default chosen for the build that cannot reach config at all.
class ReleaseControls(private val config: RemoteConfig) {

    // WRONG: read once into a val at startup. The flip never reaches a session that
    // is already open — which, during an incident, is most of them.
    //   val checkoutV2 = config.getBoolean("checkout_v2")

    fun enabled(flag: String, default: Boolean): Boolean =
        config.cached(flag) ?: default        // never blocks, never throws, works offline

    suspend fun refresh() {
        runCatching { config.fetchAndActivate(minimumInterval = 5.minutes) }
    }
}

@Composable
fun Checkout(controls: ReleaseControls) {
    // Default false for anything new: a config server you cannot reach must not be
    // able to switch a half-tested path ON for everybody.
    if (controls.enabled("checkout_v2", default = false)) CheckoutV2() else CheckoutV1()
}

// Refresh on resume as well as on launch, or the flag reaches nobody who was already
// in the app when you flipped it.
LaunchedEffect(Unit) {
    lifecycle.repeatOnLifecycle(Lifecycle.State.RESUMED) { controls.refresh() }
}

// The store-side levers are HTTP calls — script them before the incident, not during:
//   Play:  PATCH androidpublisher/v3/applications/{pkg}/edits/{id}/tracks/production
//          { "releases": [{ "versionCodes": ["4213"], "status": "halted" }] }
//   Apple: PATCH appstoreconnect/v1/appStoreVersionPhasedReleases/{id}
//          { "data": { "attributes": { "phasedReleaseState": "PAUSED" } } }
//
// Neither one uninstalls anything. Only the flag reaches phones that already updated.
